{"l":8470,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Missing the bus means ___ for another hour.'","o":["waiting","to wait","wait","waited"],"a":"waiting","r":"'Mean + -ing' betyder indebære: at misse bussen indebærer at vente."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at koste en formue' på engelsk?","o":["to break the ice","to break the bank","to break the rules","to hit the jackpot"],"a":"to break the bank","r":"'to break the bank' betyder at koste en formue. 'It won't break the bank' = det bliver ikke for dyrt."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'om end' på engelsk i 'a small, ___ important, change'?","o":["hence","thus","albeit","merely"],"a":"albeit","r":"'Albeit' = om end, selvom."},
{"l":8500,"g":8,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sårbare' på engelsk i 'Older people are more ___ to the virus'?","o":["valuable","visible","reliable","vulnerable"],"a":"vulnerable","r":"'Vulnerable' = sårbar."},
{"l":8510,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'It was my grandmother ___ taught me to knit.'","o":["who","which","whose","whom"],"a":"who","r":"I den kløvede sætning 'It was ... who ...' er bedstemoren subjekt og en person, så man bruger 'who'."},
{"l":8530,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil sige til en ven, at vedkommende ikke skal blive så ophidset?","o":["Don't get so worked out.","Don't get so worked up.","Don't get so wound down.","Don't get so heated off."],"a":"Don't get so worked up.","r":"'Get worked up' betyder at blive ophidset. 'Work out' betyder at træne eller finde ud af noget."},
{"l":8550,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'keep at it' i 'Your drawing is getting better, so keep at it.'?","o":["pas godt på den","gem den til senere","bliv ved med det","hold op med det"],"a":"bliv ved med det","r":"'Keep at it' betyder at blive ved og ikke give op."},
{"l":8560,"g":8,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The film was described by one critic as ambitious, which, given the two-hour running time and the minimal plot, may have been the kindest word available.' Hvad mener kritikeren reelt?","o":["At filmen var et ambitiøst mesterværk","At filmen havde alt for mange handlinger","At filmen var for kort til historien","At filmen var for lang og tynd i handlingen"],"a":"At filmen var for lang og tynd i handlingen","r":"'The kindest word available' antyder, at 'ambitious' er en høflig omskrivning; filmen var lang og havde næsten ingen handling."},
{"l":8580,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Never before ___ so many people at the school concert.'","o":["had there been","there had been","there were","were there being"],"a":"had there been","r":"'Never before' først i sætningen kræver inversion: 'had there been'."},
{"l":8600,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'I wish my neighbours ___ playing loud music every night.'","o":["will stop","would stop","are stopping","have stopped"],"a":"would stop","r":"'I wish + would' bruges om en irriterende vane, man ønsker ændret."},
{"l":8630,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'a stone's throw' i 'Our school is just a stone's throw from the beach.'?","o":["langt væk","på den anden side","meget tæt på","med udsigt over"],"a":"meget tæt på","r":"'A stone's throw from' betyder meget tæt på, så tæt at man næsten kunne kaste en sten derhen."},
{"l":8650,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Were it not for the bridge, the island ___ cut off from the mainland.'","o":["will be","would have","is","would be"],"a":"would be","r":"'Were it not for' er en inverteret type 2-betingelse om nutiden, så hovedsætningen har 'would be'."},
{"l":8690,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'udnytte' på engelsk?","o":["exploit","explore","explode","expose"],"a":"exploit","r":"'Exploit' betyder at udnytte. 'Explore' betyder at udforske, og 'expose' betyder at afsløre."},
{"l":8700,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The girl ___ next to the window is our new classmate.'","o":["sits","sitting","is sitting","to sit"],"a":"sitting","r":"'Sitting next to the window' er en forkortet relativsætning (= who is sitting). 'Is sitting' ville give to verber."},
{"l":8720,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Rarely ___ such a beautiful sunset over the fjord.'","o":["I have seen","I saw","have I seen","saw I"],"a":"have I seen","r":"Negative adverbier som 'Rarely' først i sætningen kræver inversion: hjælpeverbum før subjekt, 'have I seen'."},
{"l":8750,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Grandad claims that, in his day, children walked ten kilometres to school, uphill both ways.' Hvad antyder skribenten om bedstefar?","o":["At skolevejen var meget smuk","At børn i dag går for lidt","At han boede i bjergene","At han overdriver kraftigt"],"a":"At han overdriver kraftigt","r":"Det er umuligt at gå op ad bakke begge veje, så 'claims' og detaljen viser, at bedstefar overdriver."},
{"l":8800,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'feeble' i 'a feeble excuse'?","o":["weak","honest","clever","rude"],"a":"weak","r":"'Feeble' betyder svag eller tynd, altså 'weak'. En 'feeble excuse' er en dårlig undskyldning."},
{"l":8820,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'adept' i 'adept at chess'?","o":["hopeless","skilled","interested","new"],"a":"skilled","r":"'Adept at' betyder dygtig til, altså 'skilled'. 'Hopeless at' betyder det modsatte."},
{"l":8840,"g":9,"b":1,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'replenish' i 'replenish the water supply'?","o":["reduce","test","refill","protect"],"a":"refill","r":"'Replenish' betyder at genopfylde, altså 'refill'."},
{"l":8880,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'åbenlys' på engelsk i 'It was a ___ attempt to copy someone else's homework.'?","o":["blank","bland","brutal","blatant"],"a":"blatant","r":"'Blatant' betyder åbenlys og skamløs. 'Bland' betyder smagløs, og 'blank' betyder tom."},
{"l":8910,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'It's not the price ___ worries me, it's the quality.'","o":["that","what","who","how"],"a":"that","r":"Kløvet sætning: 'It's not X that ...' fremhæver, hvad der bekymrer. 'What' kan ikke bruges i denne konstruktion."},
{"l":8950,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'cluttered' i 'a cluttered desk'?","o":["busy","tidy","wooden","heavy"],"a":"tidy","r":"'Cluttered' betyder rodet og fyldt med ting, så det modsatte er 'tidy' (ryddelig)."},
{"l":8990,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'It could be argued that homework in the lower grades does more harm than good, though the evidence is far from conclusive.' Hvordan fremlægger skribenten sit synspunkt?","o":["Skråsikkert og uden tvivl","Vredt og meget personligt","Forsigtigt og med forbehold","Humoristisk og let"],"a":"Forsigtigt og med forbehold","r":"'It could be argued' og 'far from conclusive' er forsigtige formuleringer, der tager forbehold."},
{"l":9000,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Only by working together ___ solve the problem.'","o":["we can","could we have","we could have","can we"],"a":"can we","r":"'Only by ...' først i sætningen kræver inversion: 'can we solve'. 'Could we have' passer ikke med grundformen 'solve'."},
{"l":9008,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'iøjnefaldende' på engelsk?","o":["conspicuous","continuous","conscientious","contagious"],"a":"conspicuous","r":"'Conspicuous' = iøjnefaldende."},
{"l":9019,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'kynisk' på engelsk?","o":["clinical","cynical","cyclical","typical"],"a":"cynical","r":"'Cynical' = kynisk."},
{"l":9020,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'What happened ___ that the ferry left without us.'","o":["had","did","was","were"],"a":"was","r":"I den kløvede sætning 'What happened was that ...' er 'What happened' ental-subjekt for 'was'."},
{"l":9040,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ the instructions carefully, he started assembling the bookshelf.'","o":["Being read","Had read","To have read","Having read"],"a":"Having read","r":"'Having read' er en perfektum-participiumsætning: han læste først vejledningen og gik derefter i gang."},
{"l":9043,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ondsindet' på engelsk?","o":["malicious","delicious","judicious","auspicious"],"a":"malicious","r":"'Malicious' = ondsindet."},
{"l":9050,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The success of the project will ___ largely on the weather.'","o":["consist","depend","insist","persist"],"a":"depend","r":"'Depend on' betyder at afhænge af. 'Consist' kræver 'of', og 'insist' og 'persist' giver ikke mening her."},
{"l":9054,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'uundgåelig' på engelsk?","o":["invisible","inedible","inevitable","irritable"],"a":"inevitable","r":"'Inevitable' betyder uundgåelig."},
{"l":9066,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'relevant' på engelsk?","o":["permanent","persistent","impertinent","pertinent"],"a":"pertinent","r":"'Pertinent' = relevant."},
{"l":9077,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'næsvis / fræk' på engelsk?","o":["impertinent","pertinent","impatient","irrelevant"],"a":"impertinent","r":"'Impertinent' = uforskammet."},
{"l":9080,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'I'd sooner ___ at home than go to that crowded concert.'","o":["staying","stay","to stay","stayed"],"a":"stay","r":"'Would sooner' betyder det samme som 'would rather' og efterfølges af grundformen uden 'to'."},
{"l":9089,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ligeglad' på engelsk?","o":["different","indignant","indifferent","independent"],"a":"indifferent","r":"'Indifferent' = ligeglad."},
{"l":9100,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'To say that the first rehearsal did not go entirely to plan would be something of an understatement.' Hvordan gik den første prøve?","o":["Næsten perfekt","Helt efter planen","Lidt bedre end ventet","Rigtig dårligt"],"a":"Rigtig dårligt","r":"'Something of an understatement' betyder, at 'not entirely to plan' er en stor underdrivelse; det gik meget dårligt."},
{"l":9101,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overflødig / afskediget' på engelsk?","o":["redundant","abundant","reluctant","recurrent"],"a":"redundant","r":"'Redundant' betyder overflødig. 'Made redundant' betyder fyret pga. nedskæringer."},
{"l":9112,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'nidkær' på engelsk?","o":["jealous","zealous","callous","jovial"],"a":"zealous","r":"'Zealous' = nidkær, ivrig."},
{"l":9124,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overfladisk / letsindig' på engelsk?","o":["fabulous","furious","frivolous","ferocious"],"a":"frivolous","r":"'Frivolous' = uden alvor."},
{"l":9136,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forværres' på engelsk?","o":["determine","decorate","deliberate","deteriorate"],"a":"deteriorate","r":"'Deteriorate' betyder at blive værre."},
{"l":9140,"g":9,"b":2,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'reprimanded' i 'The referee reprimanded the player for wasting time.'?","o":["irettesatte","roste","udviste","trøstede"],"a":"irettesatte","r":"'Reprimand' betyder at irettesætte nogen. At blive udvist hedder 'be sent off'."},
{"l":9147,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'lindre' på engelsk?","o":["alienate","alleviate","allocate","abbreviate"],"a":"alleviate","r":"'Alleviate' betyder at lindre, fx smerte eller problemer."},
{"l":9150,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Had we left ten minutes earlier, we ___ the train.'","o":["would catch","will have caught","would have caught","had caught"],"a":"would have caught","r":"'Had we left' er en inverteret type 3-betingelse (= If we had left), så hovedsætningen skal have 'would have' + kort tillægsform."},
{"l":9160,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'mediocre' i 'The food was mediocre, but the view was fantastic.'?","o":["fremragende","kold","dyr","middelmådig"],"a":"middelmådig","r":"'Mediocre' betyder middelmådig, hverken god eller dårlig. 'But' viser kontrasten til den fantastiske udsigt."},
{"l":9170,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'uhåndterlig' på engelsk?","o":["cumbersome","quarrelsome","wholesome","handsome"],"a":"cumbersome","r":"'Cumbersome' = klodset, besværlig."},
{"l":9180,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'overbevisende' på engelsk i 'Her argument was so ___ that the whole class changed its mind.'?","o":["pervasive","persuasive","permissive","perceptive"],"a":"persuasive","r":"'Persuasive' betyder overbevisende. 'Permissive' betyder eftergivende, og 'perceptive' betyder skarpsindig."},
{"l":9182,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'undervurdere' på engelsk?","o":["overestimate","underperform","underestimate","investigate"],"a":"underestimate","r":"'Underestimate' betyder at undervurdere."},
{"l":9194,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'evig / vedvarende' på engelsk?","o":["punctual","perceptual","spiritual","perpetual"],"a":"perpetual","r":"'Perpetual' = evig."},
{"l":9205,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sandsynlig / troværdig' på engelsk?","o":["plausible","passable","palpable","laudable"],"a":"plausible","r":"'Plausible' betyder, at noget lyder troværdigt."},
{"l":9210,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'bland' i 'bland food'?","o":["cheap","spicy","raw","fresh"],"a":"spicy","r":"'Bland' betyder smagløs eller kedelig i smagen, så det modsatte er 'spicy' (krydret)."},
{"l":9220,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The head teacher insisted that the new uniform rule was final. A week later, after hundreds of complaints from pupils, it was quietly dropped.' Hvad antyder teksten?","o":["At reglen blev gjort endnu strengere","At eleverne aldrig klagede over reglen","At reglen stille og roligt blev opgivet","At skolelederen fik en ny uniform"],"a":"At reglen stille og roligt blev opgivet","r":"'Quietly dropped' betyder, at reglen blev droppet uden at man gjorde opmærksom på det, selv om den blev kaldt endelig."},
{"l":9230,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'benign' i 'a benign climate'?","o":["sunny","stable","tropical","harsh"],"a":"harsh","r":"'Benign' betyder mild og venlig, så det modsatte er 'harsh' (barsk)."},
{"l":9240,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'stringent / grundig' på engelsk?","o":["rigorous","vigorous","ridiculous","generous"],"a":"rigorous","r":"'Rigorous' = meget grundig."},
{"l":9252,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'enighed' på engelsk?","o":["census","consensus","conscience","consequence"],"a":"consensus","r":"'Consensus' = bred enighed."},
{"l":9260,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'It is high time we ___ the climate seriously.'","o":["take","will take","took","have taken"],"a":"took","r":"Efter 'It is high time' bruges datid ('took'), selv om det handler om nu: det burde allerede ske."},
{"l":9263,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'modbevise' på engelsk?","o":["refuse","repute","recruit","refute"],"a":"refute","r":"'Refute' = modbevise."},
{"l":9275,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'veltalende' på engelsk?","o":["eloquent","elegant","eminent","frequent"],"a":"eloquent","r":"'Eloquent' betyder veltalende."},
{"l":9290,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'exquisite' i 'The museum displays exquisite jewellery from the Viking Age.'?","o":["billige","udsøgte","tunge","simple"],"a":"udsøgte","r":"'Exquisite' betyder udsøgt og meget smuk og fint udført."},
{"l":9298,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'kortfattet' på engelsk?","o":["concave","conscious","concise","coarse"],"a":"concise","r":"'Concise' betyder kort og præcis i formen."},
{"l":9308,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bringe i fare' på engelsk?","o":["legitimise","patronise","jettison","jeopardise"],"a":"jeopardise","r":"'Jeopardise' betyder at sætte noget på spil."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omgå' på engelsk?","o":["circumvent","circulate","comprehend","commemorate"],"a":"circumvent","r":"'Circumvent' = omgå (fx regler)."},
{"l":9320,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil sige, at noget er alt for dyrt til ens budget?","o":["It's over my money.","It's out of my price range.","It's out of my pocket.","It's beyond my wallet."],"a":"It's out of my price range.","r":"'Out of my price range' betyder, at prisen er højere end det, man har råd til. De andre vendinger er ikke faste udtryk."},
{"l":9330,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The new rules ___ a serious threat to small local shops.'","o":["set","place","pose","bring"],"a":"pose","r":"Den faste forbindelse er 'pose a threat' (udgøre en trussel)."},
{"l":9333,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'svinde ind' på engelsk?","o":["swindle","dawdle","kindle","dwindle"],"a":"dwindle","r":"'Dwindle' = blive gradvist mindre."},
{"l":9345,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'mandat' på engelsk i 'The government has a ___ to act'?","o":["mandate","mantra","menace","motive"],"a":"mandate","r":"'Mandate' = bemyndigelse."},
{"l":9356,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'offentlig granskning' på engelsk i 'The plan came under public ___'?","o":["security","scrutiny","scarcity","mutiny"],"a":"scrutiny","r":"'Scrutiny' = kritisk granskning."},
{"l":9368,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overveje / betragte' på engelsk?","o":["contaminate","congratulate","contemplate","consolidate"],"a":"contemplate","r":"'Contemplate' = overveje grundigt."},
{"l":9380,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at huske på' på engelsk?","o":["to bear a grudge","to bear fruit","to mind the gap","to bear in mind"],"a":"to bear in mind","r":"'to bear in mind' betyder at huske på. 'Bear in mind' betyder at huske på eller tage i betragtning."},
{"l":9390,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Few people realise that the humble potato, now a staple across Europe, was once regarded with deep suspicion.' Hvad fortæller teksten om kartoflen?","o":["At man engang var mistroisk over for den","At den altid har været meget populær","At den oprindeligt kommer fra Danmark","At den i dag sjældent spises i Europa"],"a":"At man engang var mistroisk over for den","r":"'Was once regarded with deep suspicion' betyder, at folk engang var meget mistroiske over for kartoflen."},
{"l":9400,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ by the noise, the baby started to cry.'","o":["Waking","Woken","Woke","Having woken"],"a":"Woken","r":"'Woken by the noise' er en passiv participiumsætning: babyen blev vækket af larmen."},
{"l":9420,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'If I had studied harder last year, I ___ in the top class now.'","o":["would have been","will be","would be","had been"],"a":"would be","r":"Blandet betingelse: fortiden ('had studied') påvirker nutiden ('now'), så hovedsætningen bruger 'would be'."},
{"l":9440,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Despite the brochure promising sea views, the only water visible from our hotel room was the swimming pool next to the car park.' Hvilken tone har teksten?","o":["Begejstret og glad","Neutral og saglig","Bange og nervøs","Skuffet og ironisk"],"a":"Skuffet og ironisk","r":"Kontrasten mellem havudsigt og en pool ved parkeringspladsen er ironisk og viser skuffelse."},
{"l":9470,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'innate' i 'an innate talent'?","o":["acquired","unusual","hidden","modest"],"a":"acquired","r":"'Innate' betyder medfødt, så det modsatte er 'acquired' (tillært)."},
{"l":9500,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'We needn't have ___ so early; the shop didn't open until ten.'","o":["leave","left","leaving","to leave"],"a":"left","r":"'Needn't have' + kort tillægsform betyder, at man gjorde noget, som viste sig at være unødvendigt."},
{"l":9550,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'jumped the gun' i 'They jumped the gun and started celebrating before the final whistle.'?","o":["sprang over hegnet","tabte modet helt","handlede for tidligt","var for langsomme"],"a":"handlede for tidligt","r":"'Jump the gun' betyder at handle for tidligt, før det rigtige tidspunkt."},
{"l":9570,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: '___ for your help, I would never have finished the project.'","o":["If it had not","Were it not been","Unless it had been","Had it not been"],"a":"Had it not been","r":"'Had it not been for' er en inverteret type 3-betingelse (= If it had not been for) og betyder 'uden din hjælp'."},
{"l":9580,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The final decision ___ with the head teacher, not with the pupils.'","o":["rests","depends","relies","counts"],"a":"rests","r":"'The decision rests with someone' betyder, at det er vedkommende, der har ansvaret for beslutningen. De andre verber kan ikke stå med 'with' her."},
{"l":9600,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'If I were more patient, I ___ that argument yesterday.'","o":["wouldn't start","wouldn't have started","won't start","hadn't started"],"a":"wouldn't have started","r":"Blandet betingelse: en vedvarende egenskab ('were more patient') påvirker fortiden ('yesterday'), så det er 'wouldn't have started'."},
{"l":9635,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at kun lige berøre emnet' på engelsk?","o":["to scratch your head","to test the water","to scratch the surface","to touch wood"],"a":"to scratch the surface","r":"'to scratch the surface' betyder at kun lige berøre emnet. Udtrykket betyder at behandle noget meget overfladisk."},
{"l":9650,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'So exhausted ___ after the hike that they fell asleep on the bus.'","o":["they were","had they","they had","were they"],"a":"were they","r":"Når 'So + tillægsord' står først, bruges inversion: 'So exhausted were they that ...'."},
{"l":9690,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'galvanised' i 'The flood galvanised the villagers into building a new dam.'?","o":["ansporede","skræmte","forhindrede","skuffede"],"a":"ansporede","r":"'Galvanise someone into' betyder at anspore nogen til at handle; oversvømmelsen fik landsbyen til at bygge en dæmning."},
{"l":9710,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'ostracised' i 'In ancient Athens, unpopular citizens could be ostracised for ten years.'?","o":["belønnet","forvist","valgt","fængslet"],"a":"forvist","r":"'Ostracise' betyder at udstøde eller forvise; i oldtidens Athen kunne man blive sendt væk fra byen i ti år."},
{"l":9730,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man foreslår at stoppe en diskussion og acceptere, at man ikke er enige?","o":["Let's disagree together.","Let's be agree about it.","Let's agree to disagree.","Let's agree with disagreeing."],"a":"Let's agree to disagree.","r":"'Let's agree to disagree' er det faste udtryk for at acceptere, at man har forskellige meninger."},
{"l":9760,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'nonchalant' i 'He looked nonchalant, even though the exam started in five minutes.'?","o":["rystet","forvirret","forsinket","ubekymret"],"a":"ubekymret","r":"'Nonchalant' betyder ubekymret og afslappet, selv om situationen er alvorlig."},
{"l":9780,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil vise medfølelse med en ven, hvis hund lige er død?","o":["I'm so sorry for your loss.","I'm so sorry for your lost.","I feel so pity for you.","Bad luck with your dog."],"a":"I'm so sorry for your loss.","r":"'I'm so sorry for your loss' er den faste, venlige måde at vise medfølelse på. 'Lost' er et verbum, og 'Bad luck' er alt for let."},
{"l":9810,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'At no point ___ the passengers in any danger.'","o":["did","were","had","was"],"a":"were","r":"'At no point' først i sætningen kræver inversion med verbet 'be'; 'passengers' er flertal, så det er 'were'."},
{"l":9830,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'ample' i 'ample time'?","o":["precious","limited","plentiful","valuable"],"a":"plentiful","r":"'Ample' betyder rigelig, mere end nok, altså 'plentiful'."},
{"l":9860,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'trepidation' i 'She opened the envelope with some trepidation.'?","o":["glæde","ligegyldighed","nysgerrighed","ængstelse"],"a":"ængstelse","r":"'Trepidation' betyder ængstelse eller nervøsitet for, hvad der vil ske."},
{"l":9880,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Under no circumstances ___ the laboratory without safety goggles.'","o":["should you enter","you should enter","you enter","entering"],"a":"should you enter","r":"Efter et negativt udtryk som 'Under no circumstances' først i sætningen kræves inversion: 'should you enter'."},
{"l":9920,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The weather ___ fine, we decided to eat outside.'","o":["been","being","was being","to be"],"a":"being","r":"'The weather being fine' er en absolut participiumkonstruktion med eget subjekt (= Because the weather was fine)."},
{"l":9960,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Only after the match had ended ___ how tired they were.'","o":["the players realised","realised the players","did the players realise","had realised the players"],"a":"did the players realise","r":"'Only after ...' først i sætningen kræver inversion i hovedsætningen: 'did the players realise'."},
{"l":9972,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'overflod' på engelsk?","o":["plateau","pleasure","phantom","plethora"],"a":"plethora","r":"'Plethora' = overflod."},
{"l":9995,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'sammenhæng / sammenhold' på engelsk?","o":["cohesion","collision","coercion","corrosion"],"a":"cohesion","r":"'Cohesion' = sammenhængskraft."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ulighed / forskel' på engelsk?","o":["dispersal","disparity","prosperity","depravity"],"a":"disparity","r":"'Disparity' = forskel, ulighed."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
